1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import java.util.HashSet;
8	import java.util.Set;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.rest.function.common.Localities;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	
15	/**
16	 * Assigns a new owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
17	 * region derived from the postcode alone ({@link Localities#ofPostcode}: NSW 2000-2099, VIC
18	 * 3000-3099, QLD 4000-4099, else {@code UNKNOWN}) and HASH8 is the first 8 UPPER-case hex characters
19	 * of the SHA-256 digest over {@code normalizedTelephone + lastName} (e.g. {@code NSW-3F9A0C71}).
20	 * There are no per-city sequence numbers: the identity is stable for a given telephone, surname and
21	 * region. When the computed {@code <REGION>-<HASH8>} collides with an existing owner's
22	 * {@code customerCode}, {@code -<n>} is appended with the smallest {@code n} of 2 or more that makes
23	 * it unique, so distinct owners always receive distinct codes.
24	 * Runs after {@link BuildOwner} maps the request (so the telephone is already the normalized
25	 * E.164 value) and before {@link SaveOwner} persists it; every downstream region-and-hash value (the
26	 * membership number and its check digit, the locality and the create audit record) flows from this
27	 * code.
28	 */
29	public class AssignOwnerCustomerCode {
30	
31	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
32	        String region = Localities.ofPostcode(owner.getPostcode());
33	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
34	        String base = region + "-" + hash8;
35	
36	        Set<String> taken = new HashSet<>();
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (existing.getCustomerCode() != null) {
39	                taken.add(existing.getCustomerCode());
40	            }
41	        }
42	
43	        String customerCode = base;
44	        for (int n = 2; taken.contains(customerCode); n++) {
45	            customerCode = base + "-" + n;
46	        }
47	        owner.setCustomerCode(customerCode);
48	    }
49	
50	    /** First 8 UPPER-case hex characters of SHA-256 over the UTF-8 bytes of {@code input}. */
51	    private static String hash8(String input) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                    .digest(input.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder hex = new StringBuilder(8);
56	            for (byte b : digest) {
57	                hex.append(String.format("%02X", b));
58	                if (hex.length() >= 8) {
59	                    break;
60	                }
61	            }
62	            return hex.substring(0, 8);
63	        }
64	        catch (NoSuchAlgorithmException ex) {
65	            throw new IllegalStateException("SHA-256 not available", ex);
66	        }
67	    }
68	}
