15	
16	    private FiscalYear() {
17	    }
18	
19	    /** The fiscal year (the calendar year in which it ends) that {@code date} falls in. */
20	    public static int of(LocalDate date) {
21	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
22	    }
23	
24	    /** The fiscal-year label {@code FY<YY>} (last two digits of the fiscal year) for {@code date}. */
25	    public static String label(LocalDate date) {
26	        return String.format("FY%02d", of(date) % 100);
27	    }
28	}
