12	/**
13	 * Emits, on successful create, both a human-readable audit line and an immutable structured
14	 * {@link OwnerCreatedEvent} — recording the newly-persisted owner's id, {@code customerCode},
15	 * {@code registrationDate}, {@code membershipLevel} and {@code membershipNumber} — to the dedicated
16	 * {@code AUDIT} logger. Runs after {@link SaveOwner} (so the owner has its generated id) and before
17	 * {@link RespondWithOwnerCreated}.
18	 */
19	public class AuditOwnerCreated {
20	
21	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
22	
23	    /** Monotonically increasing sequence across all creates, stamped onto each emitted event. */
24	    private static final AtomicLong SEQ = new AtomicLong();
25	
26	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
27	        Integer membershipLevel = ownerMapper.toOwnerDto(owner).getMembershipLevel();
28	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
29	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
30	                membershipLevel, owner.getMembershipNumber());
31	
32	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
33	                primaryIdentifier(owner), membershipLevel);
34	        AUDIT.info(event.toJson());
35	    }
36	
37	    /**
38	     * The owner's current primary identifier carried by the event. Today the {@code customerCode};
39	     * once the customerCode is unified into the memberId, return the memberId here so the event
40	     * carries it instead — this is the one place that resolution changes.
41	     */
42	    private static String primaryIdentifier(Owner owner) {
43	        return owner.getCustomerCode();
44	    }
45	}
