1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner &amp; OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public abstract class OwnerMapper {
22	
23	    @Autowired
24	    protected OwnerRepository ownerRepository;
25	
26	    @Mapping(target = "displayName",
27	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
28	    @Mapping(target = "initials",
29	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "salutation",
31	            expression = "java(salutation(owner))")
32	    @Mapping(target = "membershipPoints",
33	            expression = "java(membershipPoints(owner))")
34	    @Mapping(target = "membershipLevel",
35	            expression = "java(membershipLevel(owner))")
36	    @Mapping(target = "locality",
37	            expression = "java(org.springframework.samples.petclinic.rest.function.common.Localities.regionOf(owner.getCustomerCode()))")
38	    @Mapping(target = "timezone",
39	            expression = "java(org.springframework.samples.petclinic.rest.function.common.Localities.timezoneOf(owner.getCustomerCode()))")
40	    @Mapping(target = "contactPreference",
41	            expression = "java(contactPreference(owner))")
42	    @Mapping(target = "identityKey",
43	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentityKey.of(owner))")
44	    @Mapping(target = "checkDigit",
45	            expression = "java(checkDigit(owner))")
46	    @Mapping(target = "telephoneDisplay",
47	            expression = "java(telephoneDisplay(owner))")
48	    @Mapping(target = "ageBand",
49	            expression = "java(ageBand(owner))")
50	    @Mapping(target = "fiscalYear",
51	            expression = "java(fiscalYear(owner))")
52	    @Mapping(target = "ownerSegment",
53	            expression = "java(ownerSegment(owner))")
54	    @Mapping(target = "selfLink",
55	            expression = "java(owner.getId() == null ? null : \"/api/owners/\" + owner.getId())")
56	    @Mapping(target = "bulkSignupWarning", ignore = true)
57	    @Mapping(target = "capacityWarning", ignore = true)
58	    public abstract OwnerDto toOwnerDto(Owner owner);
59	
60	    public abstract Owner toOwner(OwnerDto ownerDto);
61	
62	    @Mapping(target = "id", ignore = true)
63	    @Mapping(target = "pets", ignore = true)
64	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
65	
66	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
67	
68	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
69	
70	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
71	        OwnerPageDto ownerPageDto = new OwnerPageDto();
72	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
73	        ownerPageDto.setPage(ownerPage.getNumber());
74	        ownerPageDto.setSize(ownerPage.getSize());
75	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
76	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
77	        return ownerPageDto;
78	    }
79	
80	    /**
81	     * Compose the owner's salutation: the stored title, a single space and the last name when a
82	     * title was supplied, or just the last name when no title is given.
83	     */
84	    protected String salutation(Owner owner) {
85	        String title = owner.getTitle();
86	        if (title == null || title.isBlank()) {
87	            return owner.getLastName();
88	        }
89	        return title + " " + owner.getLastName();
90	    }
91	
92	    /**
93	     * Score the owner's membership points. Starts at 0, plus 2 when an email is present, plus 1
94	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more owners, plus 3 when
95	     * tenure spans at least one elapsed fiscal year (fiscal years start 1 July). Because a newly
96	     * created owner registers within the current fiscal year it has zero tenure, so the tenure points
97	     * are only earned on later reads.
98	     */
99	    protected Integer membershipPoints(Owner owner) {
100	        int points = 0;
101	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
102	            points += 2;
103	        }
104	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount().intValue() == 0) {
105	            points += 1;
106	        }
107	        if (householdSize(owner) >= 3) {
108	            points += 2;
109	        }
110	        if (owner.getRegistrationDate() != null
111	                && org.springframework.samples.petclinic.rest.function.owner.FiscalYear.of(java.time.LocalDate.now())
112	                        - org.springframework.samples.petclinic.rest.function.owner.FiscalYear
113	                                .of(owner.getRegistrationDate()) >= 1) {
114	            points += 3;
115	        }
116	        return points;
117	    }
118	
119	    /**
120	     * The owner's membership level: its raw {@link #uncappedLevel(Owner) level from points}, subject
121	     * to the household level ceiling. A new owner's level cannot exceed one above the current maximum
122	     * level among its household members — the members (sharing its {@code householdId}) that already
123	     * existed when it was created, i.e. those with a smaller id. With no existing household member no
124	     * cap applies. The household is replayed in creation (id) order so each member is capped at one
125	     * above the running maximum of the earlier members' already-capped levels.
126	     */
127	    protected Integer membershipLevel(Owner owner) {
128	        String householdId = owner.getHouseholdId();
129	        Integer id = owner.getId();
130	        if (householdId == null || id == null) {
131	            return uncappedLevel(owner);
132	        }
133	        java.util.List<Owner> members = new java.util.ArrayList<>();
134	        for (Owner existing : ownerRepository.findAll()) {
135	            if (existing.getId() != null && existing.getId() <= id
136	                    && householdId.equals(existing.getHouseholdId())) {
137	                members.add(existing);
138	            }
139	        }
140	        members.sort(java.util.Comparator.comparingInt(Owner::getId));
141	        Integer runningMax = null;
142	        int result = uncappedLevel(owner);
143	        for (Owner member : members) {
144	            int level = uncappedLevel(member);
145	            if (runningMax != null) {
146	                level = Math.min(level, runningMax + 1);
147	            }
148	            runningMax = (runningMax == null) ? level : Math.max(runningMax, level);
149	            if (member.getId().equals(id)) {
150	                result = level;
151	            }
152	        }
153	        return result;
154	    }
155	
156	    /**
157	     * Map {@link #membershipPoints(Owner)} to a membership level from 1 to 4: level 1 for 0-1
158	     * points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
159	     */
160	    private int uncappedLevel(Owner owner) {
161	        int points = membershipPoints(owner);
162	        if (points <= 1) {
163	            return 1;
164	        }
165	        if (points <= 3) {
166	            return 2;
167	        }
168	        if (points <= 5) {
169	            return 3;
170	        }
171	        return 4;
172	    }
173	
174	    /**
175	     * The number of owners in this owner's household, identified by the shared {@code householdId}
176	     * assigned at creation. An owner with no householdId counts only as itself.
177	     */
178	    protected long householdSize(Owner owner) {
179	        String householdId = owner.getHouseholdId();
180	        if (householdId == null) {
181	            return 1;
182	        }
183	        long count = 0;
184	        for (Owner existing : ownerRepository.findAll()) {
185	            if (householdId.equals(existing.getHouseholdId())) {
186	                count++;
187	            }
188	        }
189	        return count;
190	    }
191	
192	    /**
193	     * Derive the owner's preferred contact channel: {@code EMAIL} when an email is present,
194	     * otherwise {@code PHONE}.
195	     */
196	    protected String contactPreference(Owner owner) {
197	        return (owner.getEmail() != null && !owner.getEmail().isEmpty()) ? "EMAIL" : "PHONE";
198	    }
199	
200	    /**
201	     * Derive the owner's age band from {@code birthDate} as at {@code registrationDate}:
202	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, {@code SENIOR} at 65 or over.
203	     * Returns {@code null} when no birth date was supplied.
204	     */
205	    protected String ageBand(Owner owner) {
206	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
207	            return null;
208	        }
209	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
210	        if (age < 18) {
211	            return "MINOR";
212	        }
213	        if (age < 65) {
214	            return "ADULT";
215	        }
216	        return "SENIOR";
217	    }
