219	    /**
220	     * The owner's fiscal year, formatted {@code FY<YY>} (last two digits) and derived from the
221	     * business-day-adjusted {@code registrationDate}; the fiscal year starts on 1 July. Returns
222	     * {@code null} when no registration date is set.
223	     */
224	    protected String fiscalYear(Owner owner) {
225	        return owner.getRegistrationDate() == null ? null
226	                : org.springframework.samples.petclinic.rest.function.owner.FiscalYear
227	                        .label(owner.getRegistrationDate());
228	    }
229	
230	    /** Known regions whose owners fall in the {@code METRO} area; anything else is {@code REGIONAL}. */
231	    private static final java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
232	
233	    /**
234	     * The owner's segment, formatted {@code <TIER>_<AREA>}: TIER is {@code PREMIUM} when
235	     * {@link #membershipLevel(Owner)} is 3 or more, otherwise {@code STANDARD}; AREA is {@code METRO}
236	     * when the owner's locality is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
237	     */
238	    protected String ownerSegment(Owner owner) {
239	        Integer level = membershipLevel(owner);
240	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
241	        String region = org.springframework.samples.petclinic.rest.function.common.Localities
242	                .regionOf(owner.getCustomerCode());
243	        String area = METRO_REGIONS.contains(region) ? "METRO" : "REGIONAL";
244	        return tier + "_" + area;
245	    }
246	
247	    /**
248	     * Known country codes (digits after the {@code '+'}), longest first so {@code '61'} is
249	     * matched before {@code '1'}, mirroring {@code NormalizeOwnerTelephone}.
250	     */
251	    private static final String[] COUNTRY_CODES = {"61", "1"};
252	
253	    /**
254	     * Format the stored E.164 telephone for humans: the country code, a space, then the national
255	     * digits grouped in threes from the left (e.g. {@code +61412345678} -> {@code +61 412 345 678}).
256	     * Returns the raw value unchanged when it is not a recognised E.164 number.
257	     */
258	    protected String telephoneDisplay(Owner owner) {
259	        String telephone = owner.getTelephone();
260	        if (telephone == null || !telephone.startsWith("+")) {
261	            return telephone;
262	        }
263	        String digits = telephone.substring(1);
264	        String code = null;
265	        for (String candidate : COUNTRY_CODES) {
266	            if (digits.startsWith(candidate)) {
267	                code = candidate;
268	                break;
269	            }
270	        }
271	        if (code == null) {
272	            return telephone;
273	        }
274	        String national = digits.substring(code.length());
275	        StringBuilder grouped = new StringBuilder("+").append(code);
276	        for (int i = 0; i < national.length(); i += 3) {
277	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
278	        }
279	        return grouped.toString();
280	    }
281	
282	    /**
283	     * Compute a single Luhn check digit (0-9) over the digits contained in the owner's
284	     * {@code customerCode}. Non-digit characters (such as the hyphen separators) are ignored.
285	     */
286	    protected Integer checkDigit(Owner owner) {
287	        String code = owner.getCustomerCode();
288	        if (code == null) {
289	            return null;
290	        }
291	        int sum = 0;
292	        boolean dbl = true;
293	        for (int i = code.length() - 1; i >= 0; i--) {
294	            char c = code.charAt(i);
295	            if (c < '0' || c > '9') {
296	                continue;
297	            }
298	            int d = c - '0';
299	            if (dbl) {
300	                d *= 2;
301	                if (d > 9) {
302	                    d -= 9;
303	                }
304	            }
305	            sum += d;
306	            dbl = !dbl;
307	        }
308	        return (10 - (sum % 10)) % 10;
309	    }
310	}
