1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * The single derived key that all owner duplicate detection is expressed through: the lower-case
12	 * SHA-256 hex digest (64 characters) of {@code <normalizedTelephone>|<lowerEmail>|<soundex(lastName)>}.
13	 * The telephone is the normalized E.164 form, the email is the lower-cased address (empty when
14	 * absent) and the last-name component is its {@link OwnerSoundex} code, so the key groups
15	 * phonetically-equal surnames. Two owners are duplicates only when their whole identityKey is equal —
16	 * because the telephone is part of the key, owners with the same last name and postcode but different
17	 * telephones have different keys and are both allowed (flagged instead as a soft match).
18	 */
19	public final class OwnerIdentityKey {
20	
21	    private OwnerIdentityKey() {
22	    }
23	
24	    /** The identity key of a stored owner, from its telephone, email and last name. */
25	    public static String of(Owner owner) {
26	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
27	    }
28	
29	    /** The identity key for the given normalized telephone, email and last name. */
30	    public static String of(String telephone, String email, String lastName) {
31	        String material = safe(telephone) + "|" + lowerEmail(email) + "|" + OwnerSoundex.of(lastName);
32	        return sha256hex(material);
33	    }
34	
35	    private static String safe(String value) {
36	        return value == null ? "" : value;
37	    }
38	
39	    private static String lowerEmail(String email) {
40	        return email == null ? "" : email.toLowerCase(Locale.ROOT);
41	    }
42	
43	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
44	    private static String sha256hex(String value) {
45	        try {
46	            byte[] digest = MessageDigest.getInstance("SHA-256")
47	                    .digest(value.getBytes(StandardCharsets.UTF_8));
48	            StringBuilder sb = new StringBuilder(digest.length * 2);
49	            for (byte b : digest) {
50	                sb.append(String.format("%02x", b));
51	            }
52	            return sb.toString();
53	        }
54	        catch (NoSuchAlgorithmException ex) {
55	            throw new IllegalStateException("SHA-256 not available", ex);
56	        }
57	    }
58	}
