1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * The single duplicate check on {@code POST /api/owners}, keyed off the {@link OwnerIdentityKey} —
11	 * the SHA-256 digest of {@code <telephone>|<email>|<soundex(lastName)>}. Rejects with 409 via
12	 * {@link DuplicateIdentityException} when the new owner's whole identity key equals an existing
13	 * owner's — an exact duplicate.
14	 *
15	 * <p>Because the telephone is part of the key, owners with the same last name and postcode but
16	 * different telephones have different keys and are both allowed — such a soft match is not rejected
17	 * here; it is flagged instead by {@link AssignOwnerPossibleDuplicate}. There is no longer a separate
18	 * household-duplicate block: the single identity key is the whole duplicate rule.
19	 *
20	 * <p>Runs before {@link BuildOwner} so no owner is created on conflict. Soft-deleted owners are
21	 * ignored, so a re-registration after a delete is allowed.
22	 */
23	public class CheckUniqueOwnerIdentity {
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(),
28	                request.getLastName());
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (Boolean.TRUE.equals(existing.getDeleted())) {
31	                continue; // a soft-deleted owner does not block a new registration
32	            }
33	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
34	                throw new DuplicateIdentityException(identityKey);
35	            }
36	        }
37	    }
38	}
