7	/**
8	 * Business-day rules for owner registration. A registration date must fall on a business day:
9	 * when it lands on a Saturday, Sunday or a listed public holiday it rolls forward to the next
10	 * non-holiday weekday. Used both to adjust the effective registration date (see
11	 * {@link DefaultOwnerRegistrationDate}) and to bucket the daily create-limit (see
12	 * {@link CheckDailyOwnerLimit}) so both share one definition.
13	 */
14	final class BusinessDay {
15	
16	    /** Fixed public holidays the business-day roll skips. */
17	    private static final Set<LocalDate> HOLIDAYS = Set.of(
18	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
19	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
20	            LocalDate.parse("2026-12-28"));
21	
22	    private BusinessDay() {
23	    }
24	
25	    /**
26	     * Roll {@code date} forward over Saturdays, Sundays and listed public holidays to the next
27	     * non-holiday business day; a weekday that is not a holiday is unchanged.
28	     */
29	    static LocalDate rollForward(LocalDate date) {
30	        while (isWeekend(date) || HOLIDAYS.contains(date)) {
31	            date = date.plusDays(1);
32	        }
33	        return date;
34	    }
35	
36	    private static boolean isWeekend(LocalDate date) {
37	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
38	    }
39	}
